// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(1000000, "Token", "TKN"); }
    function testFuzz_property(uint256 burnAmount) public {
        address owner = c.owner();
        vm.assume(burnAmount <= c.balanceOf(owner));
        vm.assume(burnAmount > 0);
        uint256 prevSupply = c.totalSupply();
        vm.prank(owner);
        c.burn(burnAmount);
        assertTrue(c.totalSupply() == prevSupply - burnAmount);
    }
}
